const item = $input.first().json;

const prompt = `# Script Agent Prompt

Ты Script Agent для контент-машины вертикальных видео.

Твоя задача: превратить входную идею в готовую структуру ролика для Reels, TikTok или YouTube Shorts.

## Входные данные

ID идеи:
${item.id}

Тема:
${item.topic}

Целевая аудитория:
${item.audience}

Платформа:
${item.platform}

Длительность:
${item.duration_seconds} секунд

Тональность:
${item.tone}

Цель:
${item.goal}

Ограничения:
${item.constraints}

## Требования к результату

Верни результат строго в Markdown.

Структура ответа:

# ${item.id}. Сценарий вертикального видео

## 1. Название ролика

Короткое рабочее название.

## 2. Цель ролика

Кратко объясни, что должен сделать ролик.

## 3. Хук

Одна сильная фраза для первых 1-3 секунд.

## 4. Структура ролика

| Блок | Время | Содержание | Визуал | Текст на экране |
|---|---:|---|---|---|

Обязательные блоки:

- Hook;
- Setup;
- Main value;
- Payoff;
- CTA.

## 5. Voiceover

Полный текст озвучки.

## 6. On-screen text

Список надписей на экране по сценам.

## 7. Scene prompts

Для каждой сцены укажи:

- номер сцены;
- что происходит;
- визуальный стиль;
- движение камеры;
- важные ограничения.

## 8. CTA

Финальный призыв к действию.

## 9. 5 альтернативных хуков

Список из пяти вариантов.

## Ограничения

- Не добавляй факты, которых нет во входных данных.
- Не используй длинное вступление.
- Не пиши канцеляритом.
- Не делай сценарий длиннее указанной длительности.
- Пиши на русском языке.
- Делай текст пригодным для вертикального видео.`;

return [
  {
    json: {
      id: item.id,
      prompt,
    },
  },
];

const item = $input.first().json;

const scriptMarkdown =
  item.output?.[0]?.content?.[0]?.text ||
  item.output?.content?.[0]?.text ||
  item.text ||
  '';

return [
  {
    json: {
      id: 'idea_001',
      script_markdown: scriptMarkdown,
      generated_at: new Date().toISOString(),
      source: 'openai',
    },
  },
];

const item = $input.first().json;

const scriptMarkdown = item.script_markdown || '';

const videoPayload = {
  id: item.id,
  format: 'vertical_video',
  aspect_ratio: '9:16',
  platform: 'reels_tiktok_shorts',
  language: 'ru',
  duration_seconds: 30,
  source: item.source || 'openai',
  generated_at: item.generated_at,
  script_markdown: scriptMarkdown,
  production_status: 'script_ready',
  next_step: 'video_generation',
  video_requirements: {
    resolution: '1080x1920',
    captions: true,
    voiceover: true,
    background_music: true,
    safe_zones: true
  }
};

return [
  {
    json: {
      id: item.id,
      video_payload: videoPayload
    }
  }
];

const item = $input.first().json;

return [
  {
    json: {
      id: item.id,
      status: 'ready_for_video_generation',
      video_payload: item.video_payload,
      completed_at: new Date().toISOString()
    }
  }
];

const item = $input.first().json;

const videoPayload = item.video_payload || {};
const scriptMarkdown = videoPayload.script_markdown || '';

function extractSection(markdown, heading) {
  const escapedHeading = heading.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const regex = new RegExp(`##\\s+${escapedHeading}\\s*\\n([\\s\\S]*?)(?=\\n##\\s+|$)`, 'i');
  const match = markdown.match(regex);
  return match ? match[1].trim() : '';
}

function firstNonEmptyLine(text) {
  return text
    .split('\n')
    .map(line => line.trim())
    .filter(line => line && !line.startsWith('|') && !line.startsWith('---'))[0] || '';
}

function parseStructureTable(markdown) {
  const section = extractSection(markdown, '4. Структура ролика');
  const lines = section
    .split('\n')
    .map(line => line.trim())
    .filter(line => line.startsWith('|'));

  const dataLines = lines.filter(line => {
    return !line.includes('---') && !line.includes('Блок') && line.split('|').length >= 6;
  });

  return dataLines.map((line, index) => {
    const cells = line
      .split('|')
      .map(cell => cell.trim())
      .filter(Boolean);

    return {
      scene: index + 1,
      block: cells[0] || '',
      duration: cells[1] || '',
      content: cells[2] || '',
      visual: cells[3] || '',
      on_screen_text: cells[4] || ''
    };
  });
}

function extractCaptions(markdown, scenes) {
  const onScreenTextSection = extractSection(markdown, '6. On-screen text');

  if (onScreenTextSection) {
    return onScreenTextSection
      .split('\n')
      .map(line => line.trim())
      .map(line => line.replace(/^\d+\.\s*/, '').replace(/^[-*]\s*/, '').trim())
      .filter(Boolean);
  }

  return scenes
    .map(scene => scene.on_screen_text)
    .filter(Boolean);
}

const scenes = parseStructureTable(scriptMarkdown);

const title = firstNonEmptyLine(extractSection(scriptMarkdown, '1. Название ролика'));
const voiceover = extractSection(scriptMarkdown, '5. Voiceover');
const captions = extractCaptions(scriptMarkdown, scenes);
const cta = firstNonEmptyLine(extractSection(scriptMarkdown, '8. CTA'));

const videoPipelineJson = {
  id: item.id || videoPayload.id || '',
  title,
  duration_seconds: videoPayload.duration_seconds || 30,
  language: videoPayload.language || 'ru',
  aspect_ratio: videoPayload.aspect_ratio || '9:16',
  resolution: videoPayload.video_requirements?.resolution || '1080x1920',
  voiceover,
  captions,
  scenes,
  cta,
  source_script_format: 'markdown'
};

return [
  {
    json: {
      id: item.id || videoPayload.id || '',
      status: 'ready_for_video_pipeline',
      video_pipeline_json: videoPipelineJson,
      source_video_payload: videoPayload,
      completed_at: new Date().toISOString()
    }
  }
];

const item = $input.first().json;

const pipeline = item.video_pipeline_json || {};

function cleanText(value) {
  return String(value || '').replace(/\s+/g, ' ').trim();
}

function buildSearchTerms(scene) {
  const text = `${scene.block || ''} ${scene.content || ''} ${scene.visual || ''}`.toLowerCase();

  if (text.includes('hockey') || text.includes('хоккей') || text.includes('форма')) {
    return ['hockey', 'sports design', 'technology'];
  }

  if (text.includes('ai') || text.includes('ии') || text.includes('искусственный интеллект')) {
    return ['artificial intelligence', 'creative process', 'technology'];
  }

  return ['sports', 'technology', 'creative process'];
}

const scenes = Array.isArray(pipeline.scenes) ? pipeline.scenes : [];

const shortVideoScenes = scenes.map((scene) => {
  const text =
    cleanText(scene.content) ||
    cleanText(scene.on_screen_text) ||
    cleanText(pipeline.voiceover);

  return {
    text,
    searchTerms: buildSearchTerms(scene),
  };
}).filter(scene => scene.text);

const fallbackScenes = [
  {
    text: cleanText(pipeline.voiceover) || cleanText(pipeline.title) || 'Короткое вертикальное видео для теста контент-машины.',
    searchTerms: ['sports', 'technology', 'creative process'],
  },
];

const shortVideoMakerPayload = {
  scenes: shortVideoScenes.length ? shortVideoScenes : fallbackScenes,
  config: {
    paddingBack: 1500,
    music: 'excited',
    captionPosition: 'bottom',
    captionBackgroundColor: 'blue',
    voice: 'af_heart',
    orientation: 'portrait',
    musicVolume: 'medium',
  },
};

return [
  {
    json: {
      id: item.id || pipeline.id || '',
      status: 'ready_for_short_video_maker',
      short_video_maker_payload: shortVideoMakerPayload,
      source_video_pipeline_json: pipeline,
      completed_at: new Date().toISOString(),
    },
  },
];

const item = $input.first().json;

const videoId = item.videoId || '';

return [
  {
    json: {
      id: 'idea_001',
      status: videoId ? 'short_video_generation_started' : 'short_video_generation_failed',
      videoId,
      status_url: videoId ? `http://host.docker.internal:3123/api/short-video/${videoId}/status` : '',
      video_url: videoId ? `http://host.docker.internal:3123/api/short-video/${videoId}` : '',
      browser_url: videoId ? `http://localhost:3123/video/${videoId}` : '',
      source: 'short-video-maker',
      created_at: new Date().toISOString(),
    },
  },
];

const statusItem = $input.first().json;

// Берём данные из предыдущего node Normalize Short Video Response
const normalized = $('Normalize Short Video Response').first().json;

const videoId = normalized.videoId || '';
const renderStatus = statusItem.status || 'unknown';

return [
  {
    json: {
      id: normalized.id || 'idea_001',
      status: renderStatus === 'ready'
        ? 'short_video_ready'
        : 'short_video_not_ready',
      render_status: renderStatus,
      videoId,
      status_url: normalized.status_url || '',
      video_url: normalized.video_url || '',
      browser_url: normalized.browser_url || '',
      source: normalized.source || 'short-video-maker',
      completed_at: new Date().toISOString(),
    },
  },
];
